use crate::aap::caps::state_rw;
use std::collections::HashSet;

struct Node;

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        let mut recorded: u32 = 0;
        // Only mark items as seen once the digest has actually been published.
        if published.published {
            let mut done: HashSet<&str> = HashSet::new();
            for id in published.considered.iter() {
                if done.insert(id.as_str()) {
                    state_rw::put(id, &published.date);
                    recorded += 1;
                }
            }
        }
        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
